import './StatusList.css';
import type { Status, StatusItem } from '../../types';

export const STATUS_LABELS: Record<Status, string> = {
  'todo': 'To Do',
  'in-progress': 'In Progress',
  'done': 'Done',
  'blocked': 'Blocked',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: Status): string {
  if (status === 'todo') return 'status-color-todo';
  if (status === 'in-progress') return 'status-color-in-progress';
  if (status === 'done') return 'status-color-done';
  return 'status-color-blocked';
}

const STATUS_ORDER: Status[] = ['todo', 'in-progress', 'done', 'blocked'];

interface StatusListProps {
  items: StatusItem[] | null;
}

export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    return (
      <ul className="status-list" aria-label="Loading items" aria-busy="true">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="status-list-item">
            <span className="skeleton-item status-list-item-label" />
          </li>
        ))}
      </ul>
    );
  }

  const grouped = STATUS_ORDER.reduce<Record<Status, StatusItem[]>>(
    (acc, status) => {
      acc[status] = items.filter((item) => item.status === status);
      return acc;
    },
    { todo: [], 'in-progress': [], done: [], blocked: [] },
  );

  return (
    <ul className="status-list" aria-label="Status list">
      {STATUS_ORDER.map((status) => {
        const group = grouped[status];
        if (group.length === 0) return null;
        return (
          <li key={status} className="status-list-group">
            <h2 className="status-list-group-heading">{STATUS_LABELS[status]}</h2>
            <ul className="status-list-items">
              {group.map((item) => (
                <li key={item.id} className={`status-list-item ${statusColor(item.status)}`}>
                  <span className="status-list-item-label">{item.label}</span>
                </li>
              ))}
            </ul>
          </li>
        );
      })}
    </ul>
  );
}
